import std.concurrent as conc
import std.io

pub type AppError = Failed(String)

pub fn main() effect io -> Result<(), AppError> {
    var i: Int64 = 0
    var total: Int64 = 0
    while i < 5 {
        total = total + i
        i = i + 1
    }
    if total == 10 {
        io.println("ten")
    } else {
        io.println("other")
    }
    return Ok(())
}
